31	ReduceOp::ReduceOp(Array<PrimExpr> args, Map<String, ObjectRef> annotations) {
32	  ObjectPtr<ReduceOpNode> node = tvm::ffi::make_object<ReduceOpNode>();
33	  // Accept BufferRegion/BufferLoad for src/dst
34	  node->srcRegion_ = NormalizeToBufferRegion(args[0]);
35	  node->dstRegion_ = NormalizeToBufferRegion(args[1]);
36	  node->src = node->srcRegion_->buffer;
37	  node->dst = node->dstRegion_->buffer;
38	  std::string reduce_type = args[2].as<StringImm>().value()->value;
39	  node->dim = args[3].as<IntImm>().value()->value;
40	  node->type = ReduceType(reduce_type);
41	  node->clear = args[4].as<Bool>().value();
42	  data_ = std::move(node);
43	}
