55	PrimExpr ReduceOpNode::MakeInitValue() const {
56	  auto dst_dtype = dst->dtype;
57	  auto is_int = dst_dtype.is_int();
58	  bool is_uint = dst_dtype.is_uint();
59	  auto bits = dst_dtype.bits();
60	
61	  if (type->isSum()) {
62	    return make_zero(dst->dtype);
63	  } else if (type->isAbsSum()) {
64	    return make_zero(dst->dtype);
65	  } else if (type->isMax()) {
66	    if (is_int) {
67	      return make_const(dst->dtype, -(1 << (bits - 1)));
68	    } else if (is_uint) {
69	      return make_const(dst->dtype, 0);
70	    } else {
71	      return make_const(dst->dtype, -INFINITY);
72	    }
73	  } else if (type->isMin()) {
74	    if (is_int) {
75	      return make_const(dst->dtype, (1 << (bits - 1)) - 1);
76	    } else if (is_uint) {
77	      return make_const(dst->dtype, (1 << bits) - 1);
78	    } else {
79	      return make_const(dst->dtype, INFINITY);
80	    }
81	  } else if (type->isAbsMax()) {
82	    return make_const(dst->dtype, 0);
83	  } else if (type->isBitAnd()) {
84	    if (is_int) {
85	      return make_const(dst->dtype, -1);
86	    } else if (is_uint) {
87	      return make_const(dst->dtype, (1 << bits) - 1);
88	    } else {
89	      // Should not arrive here
90	      return make_const(dst->dtype, -INFINITY);
91	    }
92	  } else if (type->isBitOr()) {
93	    return make_zero(dst->dtype);
94	  } else if (type->isBitXor()) {
95	    return make_zero(dst->dtype);
96	  } else {
97	    LOG(FATAL) << "Unsupported reduce type: " << type->type;
98	    return PrimExpr();
99	  }
100	}
101	
102	PrimExpr ReduceOpNode::MakeReduce(const PrimExpr &lhs,
103	                                  const PrimExpr &b) const {
104	  PrimExpr rhs = b;
105	  if (lhs->dtype != rhs->dtype) {
106	    rhs = Cast(lhs->dtype, rhs);
107	  }
108	  if (type->isSum()) {
109	    return lhs + rhs;
110	  } else if (type->isAbsSum()) {
111	    return lhs + Max(rhs, -rhs);
112	  } else if (type->isMax()) {
113	    return Max(lhs, rhs);
114	  } else if (type->isMin()) {
115	    return Min(lhs, rhs);
116	  } else if (type->isAbsMax()) {
117	    return Max(tvm::abs(lhs), tvm::abs(rhs));
118	  } else if (type->isBitAnd()) {
119	    return lhs & rhs;
120	  } else if (type->isBitOr()) {
121	    return lhs | rhs;
122	  } else if (type->isBitXor()) {
123	    return lhs ^ rhs;
124	  } else {
125	    LOG(FATAL) << "Unsupported reduce type: " << type->type;
126	  }
127	}
128	
129	std::string ReduceOpNode::MakeCodegenReducer() const {
130	  if (type->isSum()) {
131	    return "tl::SumOp";
132	  } else if (type->isAbsSum()) {
133	    return "tl::SumOp";
134	  } else if (type->isMax()) {
135	    return "tl::MaxOp";
136	  } else if (type->isMin()) {
137	    return "tl::MinOp";
138	  } else if (type->isAbsMax()) {
139	    return "tl::MaxOp";
140	  } else if (type->isBitAnd()) {
141	    return "tl::BitAndOp";
142	  } else if (type->isBitOr()) {
143	    return "tl::BitOrOp";
144	  } else if (type->isBitXor()) {
145	    return "tl::BitXorOp";
146	  } else {
147	    LOG(FATAL) << "Unsupported reduce type: " << type->type;
148	    return "";
149	  }
150	}
151	
152	/**
153	 * @brief Lower the Reduce operator to a TIR statement.
154	 *
155	 * Lowers a ReduceOpNode operating on fragment-scoped buffers into a sequence of
156	 * TIR statements implementing: optional initialization, thread-local reduction
157	 * (unrolled inner loops), inter-thread reduction via a runtime AllReduce call
158	 * (Hopper-specific `run_hopper` variant when TargetIsHopper(T.target) is true),
159	 * and an optional accumulation or copy back to the destination buffer when a
160	 * temporary clear buffer is used.
161	 *
162	 * Behavior notes:
163	 * - Only supports src and dst in "local.fragment" scope; otherwise it checks
164	 *   and aborts with "Reduce for shared memory not implemented.".
165	 * - Supports both 1D reductions (scalar output) and reductions along a single
166	 *   extra dimension; validates layout dimensionality consistency.
167	 * - If `clear` is set (or for sum/abssum reductions), an initial value is
168	 *   written to the clear buffer; for non-clearing sum/abssum a duplicate
169	 *   temporary buffer is allocated and accumulated back into dst after
170	 * reduction.
171	 * - Performs iterator compression for local reduction loops using `analyzer`.
172	 * - Detects parallel thread splitting from the normalized iterator sum and
173	 *   emits a call to a templated `tl::AllReduce<...>::run` (or `run_hopper`)
174	 *   via `builtin::call_extern`. For sufficiently large reducing thread counts
175	 *   (>= 32) a workspace is allocated via T.AddWorkspace and passed to the
176	 *   AllReduce call.
177	 * - The final body is wrapped in parallel loops over the destination spatial
178	 *   dimensions and partitioned by the lowering thread variable. If a temporary
179	 *   clear buffer is used, it is allocated for the body.
180	 *
181	 * @param T Lowering context providing buffer and layout maps, thread bounds,
182	 *          target information, thread variable, and workspace allocation
183	 * helper.
184	 * @param analyzer Analyzer used for iterator compression and arithmetic
185	 * normalization.
186	 * @return Stmt Lowered TIR statement implementing the reduction.
187	 */
188	Stmt ReduceOpNode::Lower(const LowerArgs &T, arith::Analyzer *analyzer) const {
189	  auto get_buffer = [&](const Buffer &buf) {
190	    if (T.buffer_remap.count(buf))
191	      return T.buffer_remap[buf];
192	    return buf;
193	  };
194	
195	  auto src_scope = this->src.scope();
196	  auto dst_scope = this->dst.scope();
197	
198	  if (src_scope == "local.fragment" && dst_scope == "local.fragment") {
199	
200	    Buffer src_buffer = get_buffer(this->src);
201	    Buffer dst_buffer = get_buffer(this->dst);
202	    Fragment src_layout = T.layout_map[this->src].as<Fragment>().value();
203	    Fragment dst_layout = T.layout_map[this->dst].as<Fragment>().value();
204	    size_t src_dim = src_layout->InputDim();
205	    size_t dst_dim = dst_layout->InputDim();
206	
207	    bool is_1d_reduce = src_dim == dst_dim && dst_dim == 1;
208	
209	    if (is_1d_reduce) {
210	      ICHECK(is_one(dst_layout->OutputShape().back()))
211	          << "Reduce for scalar not implemented.";
212	    } else {
213	      ICHECK_EQ(src_dim, dst_dim + 1) << "Reduce dimension mismatch.";
214	    }
215	
216	    Array<IterVar> dst_vars;
217	    for (size_t i = 0; i < dst_dim; ++i) {
218	      Var var = Var(std::string{char('i' + i)});
219	      dst_vars.push_back(IterVar(Range(0, dst_layout->InputShape()[i]), var,
220	                                 IterVarType::kDataPar));
221	    }
222	
223	    Array<IterVar> src_vars;
224	    if (!is_1d_reduce) {
225	      src_vars = dst_vars;
226	    }
227	    Range reduce_dom(0, src_layout->InputShape()[this->dim]);
228	    IterVar reduce_iv(reduce_dom, Var("rv"), IterVarType::kDataPar);
229	    src_vars.insert(src_vars.begin() + this->dim, reduce_iv);
230	
231	    Array<PrimExpr> src_indices = src_layout->Forward(
232	        src_vars.Map([](const auto &iv) { return PrimExpr(iv->var); }));
233	    Array<PrimExpr> dst_indices = dst_layout->Forward(
234	        dst_vars.Map([](const auto &iv) { return PrimExpr(iv->var); }));
235	
236	    Array<Stmt> stmts;
237	
238	    bool require_init = this->clear;
239	    if (this->type->isSum() || this->type->isAbsSum() ||
240	        this->type->isBitAnd() || this->type->isBitOr() ||
241	        this->type->isBitXor()) {
242	      require_init = true;
243	    }
244	
245	    Buffer clear_buffer = dst_buffer;
246	    bool need_duplicate = false;
247	    if ((this->type->isSum() || this->type->isAbsSum()) && !this->clear) {
248	      need_duplicate = true;
249	    } else if (this->type->isBitAnd() && !this->clear) {
250	      need_duplicate = true;
251	    } else if ((this->type->isBitOr() || this->type->isBitXor()) &&
252	               !this->clear) {
253	      need_duplicate = true;
254	    }
255	
256	    if (need_duplicate) {
257	      // Create a new buffer with same shape and dtype as dst_buffer
258	      clear_buffer = decl_buffer(dst_buffer->shape, dst_buffer->dtype,
259	                                 dst_buffer->name + "_clear",
260	                                 GetPtrStorageScope(dst_buffer->data));
261	    }
262	    // make reduce-init stmt
263	    if (require_init) {
264	      stmts.push_back(
265	          BufferStore(clear_buffer, this->MakeInitValue(), dst_indices));
266	    }
267	
268	    // make thread-local reduce
269	    Array<PrimExpr> src_indice_compressed;
270	    Array<IterVar> src_var_compressed;
271	    for (size_t i = 0; i < src_layout->OutputDim(); ++i) {
272	      PrimExpr expr;
273	      IterVar var;
274	      std::tie(expr, var) = CompressIterator(
275	          src_indices[i], src_vars, src_vars[this->dim]->var, analyzer);
276	      src_indice_compressed.push_back(expr);
277	      src_var_compressed.push_back(var);
278	    }
279	
280	    Stmt reduce_local = BufferStore(
281	        clear_buffer,
282	        this->MakeReduce(BufferLoad(clear_buffer, dst_indices),
283	                         BufferLoad(src_buffer, src_indice_compressed)),
284	        dst_indices);
285	
286	    for (int i = static_cast<int>(src_layout->OutputDim()) - 1; i >= 0; --i) {
287	      reduce_local =
288	          For(src_var_compressed[i]->var, 0, src_var_compressed[i]->dom->extent,
289	              ForKind::kUnrolled, reduce_local, std::nullopt,
290	              {{tir::attr::pragma_unroll_explicit, Bool(false)}});
291	    }
292	    stmts.push_back(reduce_local);
293	
294	    PrimExpr src_thread = src_layout->ForwardThread(
295	        src_vars.Map([](const auto &iv) { return PrimExpr(iv->var); }), {});
296	    auto iter_sum =
297	        arith::NormalizeToIterSum(src_thread, ToVMap(src_vars), analyzer);
298	    for (const auto &iter_split : iter_sum->args) {
299	      auto mark = iter_split->source->source.as<Var>();
300	      ICHECK(mark) << "Not a normalized iterator: " << iter_split->source;
301	      if (mark.value().same_as(src_vars[this->dim]->var)) {
302	        auto scale = as_const_int(iter_split->scale);
303	        auto extent = as_const_int(iter_split->extent);
304	        ICHECK(scale != nullptr && extent != nullptr);
305	        if (*extent == 1)
306	          continue;
307	
308	        int reducing_threads = (*extent) * (*scale);
309	        std::stringstream ss;
310	
311	        auto thread_offset = T.thread_bounds->min;
312	        if (TargetIsHopper(T.target) || TargetIsSm100(T.target) ||
313	            TargetIsSM120(T.target)) {
314	          auto all_threads = T.thread_bounds->extent;
315	          ss << "tl::AllReduce<" << this->MakeCodegenReducer() << ", "
316	             << reducing_threads << ", " << (*scale) << ", " << thread_offset
317	             << ", " << all_threads << ">::run_hopper";
318	        } else {
319	          ss << "tl::AllReduce<" << this->MakeCodegenReducer() << ", "
320	             << reducing_threads << ", " << (*scale) << ", " << thread_offset
321	             << ">::run";
322	        }
323	        Array<PrimExpr> thread_reduce_args = {
324	            StringImm(ss.str()), BufferLoad(clear_buffer, dst_indices)};
325	        if (reducing_threads >= 32) {
326	          PrimExpr workspace = T.AddWorkspace(
327	              *as_const_int(T.thread_bounds->extent), clear_buffer->dtype);
328	          thread_reduce_args.push_back(workspace);
329	        }
330	        auto call = Call(clear_buffer->dtype, builtin::call_extern(),
331	                         thread_reduce_args);
332	        stmts.push_back(BufferStore(clear_buffer, call, dst_indices));
333	      }
334	    }
335	
336	    if (need_duplicate) {
337	      PrimExpr src_val = BufferLoad(clear_buffer, dst_indices);
338	      PrimExpr dst_val = BufferLoad(dst_buffer, dst_indices);
339	      PrimExpr update;
340	      if (this->type->isSum() || this->type->isAbsSum()) {
341	        update = dst_val + src_val;
342	      } else if (this->type->isBitAnd()) {
343	        update = this->clear ? src_val : bitwise_and(dst_val, src_val);
344	      } else if (this->type->isBitOr()) {
345	        update = bitwise_or(dst_val, src_val);
346	      } else if (this->type->isBitXor()) {
347	        update = bitwise_xor(dst_val, src_val);
348	      } else {
349	        LOG(FATAL) << "Unsupported reduce type: " << this->type->type;
350	      }
351	      stmts.push_back(BufferStore(dst_buffer, update, dst_indices));
352	    }
353	
354	    Stmt body = stmts.size() > 1 ? SeqStmt(stmts) : stmts[0];
355	    for (int i = static_cast<int>(dst_layout->InputDim()) - 1; i >= 0; --i) {
356	      body = For(dst_vars[i]->var, 0, dst_vars[i]->dom->extent,
357	                 ForKind::kParallel, body);
358	    }
359	
360	    if (dst_layout->InputDim() > 0) {
361	      body = PartitionLoop(Downcast<For>(body), T.thread_var, analyzer,
362	                           dst_layout);
363	    } else {
364	      PrimExpr guard = (T.thread_var == T.thread_bounds->min);
365	      body = IfThenElse(guard, body);
366	    }
367	
368	    if (need_duplicate) {
369	      body = Allocate(clear_buffer->data, clear_buffer->dtype,
370	                      clear_buffer->shape, const_true(), body);
371	    }
372	    return body;
373	  }
374	
375	  LOG(FATAL) << "Reduce for buffers in scope (" << src_scope << ", "
376	             << dst_scope << ") is not implemented.";
377	  return Stmt();
378	}
379	
380	LayoutMap ReduceOpNode::InferLayout(const LayoutInferArgs &T,
381	                                    InferLevel level) const {
382	  if (level >= InferLevel::kStrict)
383	    return {};
384	
385	  if (IsFragmentBuffer(src) && IsFragmentBuffer(dst) &&
386	      T.layout_map.count(src)) {
387	    auto src_layout = T.layout_map[src].as<Fragment>().value();
388	
389	    PrimExpr indice_rep_extent = src->shape[dim];
390	    PrimExpr src_rep_extent = src_layout->ReplicateExtent();
391	    PrimExpr dest_buffer_rep_extent = indice_rep_extent * src_rep_extent;
392	
393	    Array<PrimExpr> fwd;
394	    for (int i = 0; i < static_cast<int>(src->shape.size()); i++) {
395	      if (i == dim) {
396	        fwd.push_back(FloorMod(ReplicationPlaceholder(), indice_rep_extent));
397	      } else if (i < dim) {
398	        fwd.push_back(InputPlaceholder(i));
399	      } else if (i > dim) {
400	        fwd.push_back(InputPlaceholder(i - 1));
401	      }
402	    }
403	    auto thd = src_layout->ForwardThread(
404	        fwd, FloorDiv(ReplicationPlaceholder(), indice_rep_extent));
405	
406	    // Ensure the thread count is divisible by the replicate extent.
407	    // Otherwise, we cannot infer a valid fragment<->fragment layout.
408	    {
409	      arith::Analyzer analyzer;
410	      PrimExpr num_threads = T.thread_bounds->extent;
411	      // Though the dest_buffer_rep_extent will be compressed at
412	      // CondenseReplicateVar, we need to check the divisibility here to avoid
413	      // the issue that the thread count is not divisible by the replicate
414	      // extent.
415	      if (!analyzer.CanProve(FloorMod(num_threads, dest_buffer_rep_extent) ==
416	                             0) &&
417	          !analyzer.CanProve(FloorMod(dest_buffer_rep_extent, num_threads) ==
418	                             0)) {
419	        ICHECK(false) << "ReduceOp fragment layout inference failed: "
420	                         "num_threads % replicate_extent != 0. "
421	                      << "This mapping requires the block's thread count to be "
422	                         "divisible by the "
423	                      << "replicate extent. "
424	                      << "Try one of: (1) choose a thread block size divisible "
425	                         "by replicate_extent; "
426	                      << "(2) pick a different reduce dimension or adjust the "
427	                         "source fragment layout; "
428	                      << "Details: num_threads=" << num_threads
429	                      << ", replicate_extent=" << indice_rep_extent
430	                      << ", src=" << src << ", dst=" << dst;
431	      }
432	    }
433	
434	    Fragment dst_layout =
435	        Fragment(dst->shape, {}, thd, dest_buffer_rep_extent, std::nullopt)
436	            ->CondenseReplicateVar()
437	            ->BindThreadRange(T.thread_bounds);
438	
439	    if (!T.layout_map.count(dst))
440	      return {{dst, dst_layout}};
441	    else {
442	      // Check if computed layout is compatible with existing: the existing one
443	      // must strictly contains the computed layout
444	      auto orig_dst_layout =
445	          T.layout_map.Get(dst).value().as<Fragment>().value();
446	      ICHECK(dst_layout->InputDim() == orig_dst_layout->InputDim());
447	      Array<PrimExpr> indices;
448	      indices.reserve(dst_layout->InputDim());
449	      arith::Analyzer inner_analyzer;
450	      for (int i = 0; i < dst_layout->InputDim(); ++i) {
451	        auto x = InputPlaceholder(i);
452	        indices.push_back(x);
453	        // should be literal - literal = 0, any analyzer will work
454	        ICHECK(is_zero(inner_analyzer.Simplify(
455	            dst_layout->InputShape()[i] - orig_dst_layout->InputShape()[i])));
456	        inner_analyzer.Bind(x, Range(0, dst_layout->InputShape()[i]));
457	      }
458	
459	      ICHECK(as_const_int(dst_layout->ReplicateExtent()));
460	      ICHECK(as_const_int(src_layout->ReplicateExtent()));
461	      auto dst_rep = *as_const_int(dst_layout->ReplicateExtent());
462	      auto src_rep = *as_const_int(src_layout->ReplicateExtent());
463	      if (dst_rep < src_rep ||
464	          !ProveFragmentContains(orig_dst_layout, dst_layout, indices, indices,
465	                                 inner_analyzer)) {
466	        std::ostringstream oss;
467	        oss << "Layout may conflict with ReduceOp for buffer " << dst << " vs. "
468	            << src << "\nLHS = " << src_layout->DebugOutput()
469	            << "\nRHS = " << orig_dst_layout->DebugOutput()
470	            << "\nYou may need to use a shared memory to transform the "
471	               "layout";
472	        throw LayoutConflictException(oss.str());
473	      }
474	
475	      if (dst_rep > src_rep) {
476	        return {{dst, dst_layout}};
477	      }
478	    }
479	  }
480	  return {};
481	}
482	
483	TIR_REGISTER_TL_TILE_OP(ReduceOp, reduce)
484	    .set_num_inputs(4)
485	    .set_attr<TCallEffectKind>("TCallEffectKind",
486	                               Integer(CallEffectKind::kOpaque));
487	
488	// Normalize "Buffer" to BufferRegion. Use the shape of the buffer as the
489	// ranges.
490	static BufferRegion ConvertBufferToBufferRegion(const Buffer &buf) {
491	  Array<Range> ranges;
492	  for (PrimExpr extent : buf->shape) {
493	    ranges.push_back(Range(IntImm(extent->dtype, 0), extent));
494	  }
495	  return BufferRegion(buf, ranges);
496	}
497	
498	CumSumOp::CumSumOp(Array<PrimExpr> args, Map<String, ObjectRef> annotations) {
499	  /// CumSum constructor arguments:
500	  /// - src: input buffer
501	  /// - dst: output buffer
502	  /// - dim: dimension to cumsum
503	  /// - reverse: whether to cumsum in reverse order
504	  CHECK_EQ(args.size(), 4);
505	  ObjectPtr<CumSumOpNode> node = tvm::ffi::make_object<CumSumOpNode>();
506	  // node->src = vmap[GetVarFromAccessPtr(args[0])];
507	  // node->dst = vmap[GetVarFromAccessPtr(args[1])];
508	  node->srcRegion_ = NormalizeToBufferRegion(args[0]);
509	  node->dstRegion_ = NormalizeToBufferRegion(args[1]);
510	  node->src = node->srcRegion_->buffer;
511	  node->dst = node->dstRegion_->buffer;
512	  node->dim = args[2].as<IntImm>().value()->value;
513	  node->reverse = args[3].as<Bool>().value();
514	  CHECK_LT(node->dim, static_cast<int>(node->src->shape.size()))
515	      << "The dim of cumsum should be less than the number of dimensions. Got "
516	         "dim="
517	      << node->dim << ", but src has " << node->src->shape.size() << " dims.";
518	
519	  data_ = std::move(node);
520	}
521	
522	Stmt CumSumOpNode::Lower(const LowerArgs &T, arith::Analyzer *analyzer) const {
523	  if (IsFragmentBuffer(this->src) && IsFragmentBuffer(this->dst)) {
524	    LOG(FATAL) << "CumSum for fragment not implemented, please raise an issue "
525	                  "if you need this feature.";
526	  } else if (this->src.scope() == "shared.dyn" ||
527	             this->src.scope() == "shared") {
528	    ICHECK(this->dst.scope() == "shared.dyn" || this->dst.scope() == "shared");
529	    std::stringstream ss;
530	    auto threads = T.thread_bounds->extent;
531	    Array<PrimExpr> args;
532	
533	    // Build access pointers from regions locally
534	    PrimExpr srcPtr = MakeAccessPtrFromRegion(srcRegion_, 1);
535	    PrimExpr dstPtr = MakeAccessPtrFromRegion(dstRegion_, 2);
536	
537	    // Use region extents instead of buffer shape for correct slice handling
538	    Array<PrimExpr> src_extents;
539	    for (const auto &range : srcRegion_->region) {
540	      src_extents.push_back(range->extent);
541	    }
542	    int ndim = static_cast<int>(src_extents.size());
543	
544	    if (ndim == 1) {
545	      ICHECK_EQ(dim, 0) << "Cumulative sum over a 1D buffer only supports dim "
546	                           "= 0.";
547	      ss << "tl::CumSum1D<" << threads << ", " << (reverse ? "true" : "false")
548	         << ">::run";
549	      args = {StringImm(ss.str()), srcPtr, dstPtr, src_extents[0]};
550	    } else if (ndim == 2) {
551	      ss << "tl::CumSum2D<" << threads << ", " << dim << ", "
552	         << (reverse ? "true" : "false") << ">::run";
553	      args = {StringImm(ss.str()), srcPtr, dstPtr, src_extents[0],
554	              src_extents[1]};
555	    } else {
556	      LOG(FATAL) << "CumSum currently supports only 1D or 2D buffers, got "
557	                 << ndim << "D.";
558	    }
559	    return Evaluate(Call(dst->dtype, builtin::call_extern(), args));
560	  } else {
561	    ICHECK(false) << "Cannot lower cumsum for " << this->src.scope() << " and "
562	                  << this->dst.scope();
563	  }
564	
565	  return Stmt();
566	}
567	
568	LayoutMap CumSumOpNode::InferLayout(const LayoutInferArgs &T,
569	                                    InferLevel level) const {
570	  // Only infer layout in strict mode
571	  if (level != InferLevel::kStrict) {
572	    return {};
573	  }
574	
575	  LayoutMap result_map;
576	
577	  auto make_linear_layout = [](const Buffer &buf) -> Layout {
578	    return makeLinearLayout(buf->shape);
579	  };
580	
581	  auto check_or_set_linear_layout = [&](const Buffer &buf) {
582	    if (!IsSharedBuffer(buf))
583	      return;
584	
585	    Layout linear_layout = make_linear_layout(buf);
586	    if (T.layout_map.count(buf)) {
587	      // Check if existing layout is linear
588	      Layout existing = T.layout_map.Get(buf).value().as<Layout>().value();
589	      ICHECK(StructuralEqual()(existing, linear_layout))
590	          << "CumSum requires linear layout for shared buffer " << buf->name
591	          << ", but got non-linear layout.";
592	    } else {
593	      result_map.Set(buf, linear_layout);
594	    }
595	  };
596	
597	  check_or_set_linear_layout(src);
598	  check_or_set_linear_layout(dst);
599	
600	  return result_map;
601	}
602	
603	TIR_REGISTER_TL_TILE_OP(CumSumOp, cumsum)
604	    .set_num_inputs(4)
605	    .set_attr<TCallEffectKind>("TCallEffectKind",
606	                               Integer(CallEffectKind::kOpaque));
607	
608	TVM_FFI_STATIC_INIT_BLOCK() {
609	  ReduceOpNode::RegisterReflection();
610	  CumSumOpNode::RegisterReflection();
611	  ReduceTypeNode::RegisterReflection();
612	}
613	
614	} // namespace tl
615	} // namespace tvm
